insert into public.library_records (library_key, code, name, data, status, effective_from, notes) values
('pef_methodology','GEN-01','Reference amount','{"seq":3,"stage":"General","source_field":"Mapping sheets + ecoinvent","rule":"Emission factor = ecoinvent impact result ÷ ecoinvent reference product amount; multiply by the mapped activity amount."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','GEN-02','Missing mapping','{"seq":4,"stage":"General","source_field":"All phases","rule":"IFERROR may return 0 or blank when a mapping is missing. A zero must not automatically be interpreted as a verified zero-impact activity."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','GEN-03','Custom factors','{"seq":5,"stage":"General","source_field":"Sheet 1-4","rule":"When a custom factor is assigned, sum every mapped ecoinvent activity and its amount; do not use only the first matching row."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','GEN-04','Source hierarchy','{"seq":6,"stage":"General","source_field":"Mapping sheets","rule":"Use the dedicated mapping sheet first, then the exact ecoinvent activity, reference product and geography defined by that mapping."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-01','Substrate input','{"seq":9,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic J / Extract M","rule":"Use the exact Sourcing Hub substrate name to find the virgin, recycled, forming mappings."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-02','Material weight','{"seq":10,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic K","rule":"Calculated material weight in kg when needed (ex. SH data in thickness only)","assumption":"Assuming Density when no weight was providen"}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-03','Recycled content eligibility','{"seq":11,"stage":"Material Acquisition & Preprocessing","source_field":"Sheet 1-2 column F","rule":"Apply recycled content only when CAN_INCLUDE_RECYCLED_CONTENT is TRUE."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-04','Recycled content rate','{"seq":12,"stage":"Material Acquisition & Preprocessing","source_field":"Extract P / sheet 1-2","rule":"Use the user-provided recycled percentage when available; otherwise use the mapped default. If recycled content is not allowed, use 0%.","assumption":"Assuming default recycled %"}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-05','Virgin and recycled split','{"seq":13,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic L:M","rule":"Virgin weight = total material weight × (1 − recycled rate). Recycled weight = total material weight × recycled rate."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-06','Process efficiency','{"seq":14,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic J:K / P:Q + sheet 2-3","rule":"Apply process efficiency separately to each substrate/component, and only when that specific substrate has a distinct manufacturing/forming process mapped in sheet 1-1. Convert its net virgin and recycled weights to gross upstream inputs by dividing by the efficiency mapped in sheet 2-3. Substrates with no mapped manufacturing process keep their net weight unchanged, even when another substrate in the same product is formed. Example: for a PET cup with a silicone lid and cardboard packaging, blow-moulding efficiency applies only to the PET; silicone and cardboard remain at their net weights. This prevents process losses from one substrate being applied to all components.","assumption":"Efficiency is applied per substrate, not per product row."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-07','Virgin mapping','{"seq":15,"stage":"Material Acquisition & Preprocessing","source_field":"Sheet 1-1","rule":"Use the mapped ecoinvent activity/reference product, or the custom factor name where supplied."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-08','Recycled mapping','{"seq":16,"stage":"Material Acquisition & Preprocessing","source_field":"Sheet 1-2","rule":"Use the recycled mapping only for the recycled portion. If no valid recycled factor exists, the mapping must be reviewed rather than silently assumed equal to virgin."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-09','Custom material factor','{"seq":17,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic V:W / sheet 1-4 B:G / ecoinvent","rule":"Use a custom factor when the substrate mapping identifies a CUSTOM_FACTOR_PRODUCT_NAME instead of one direct ecoinvent dataset. Retrieve every row in sheet 1-4 with that exact custom-factor name. For each row, calculate: material amount in PEF Logic × AMOUNT_PER_1KG_OF_ACTIVITY × the matching ecoinvent factor, respecting the activity unit in sheet 1-4 (kg, m2 or m3). Then add all row impacts; do not average them and do not use only the first match. Example: 1 kg of Processed Aluminium | Virgin includes 1 kg of primary aluminium production plus 1 kg of aluminium metal working, so both impacts are added. The ecoinvent geography is matched to PO Ship From where available, with the model''s defined GLO/RER/RoW fallback. Apply the geography selection separately to every activity included in the custom factor, including embedded electricity activities. Use PO Ship From as the activity geography; if that geography is unavailable for the exact ecoinvent activity and reference product, fall back in this order: GLO, then RER, then RoW.","assumption":"The geography rule applies activity by activity, including electricity embedded in a custom material or coating factor."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-10','Coating mapping','{"seq":18,"stage":"Material Acquisition & Preprocessing","source_field":"Sheet 1-3 / sheet 1-4","rule":"Use direct ecoinvent mapping or the custom coating factor. Respect the reference unit in sheet 1-3."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-11','Coating quantity','{"seq":19,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic AK:AO / Extract S:T / sheet 1-3","rule":"Parameters:\r\nUnit: Determinate unit to be used either Kg or m2\r\nCoverage: 100% coverage except for “SPOT” Print process where we will assume 10% of coverage. \r\nSurface Area (m2): Component sizes if provided, otherwise overall flat sizes\r\nVolume (cm3)* : Overall flat sizes x 0.1millimeter thickness\r\nDensity (g/cm³): We take average density of the material (Glue, Laminated MFD, Polished Acrylic)\r\n\r\nCalculation:\r\nGrams* = Density (g/cm³) × Volume (cm³) × 50% Coverage × Order Quantity\r\nSqm (m2) = Surface area (m²) × Coverage × Order Quantity\r\nMeters (e.g., strip/tape/edge detail) = Length × Order Quantity"}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-12','Phase 1 total','{"seq":20,"stage":"Material Acquisition & Preprocessing","source_field":"PEF Logic AQ","rule":"Material Acquisition impact = virgin impact + recycled impact + coating impact."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MAT-13','Excluded','{"seq":21,"stage":"Material Acquisition & Preprocessing","source_field":"Current model boundary","rule":"Packaging beyond the modelled material fields, assembly materials and manufacturing waste are not included unless explicitly represented as a component."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-01','Factory renewable status','{"seq":24,"stage":"Manufacturing","source_field":"Factory Using Renewable / PEF Logic G","rule":"Use the mapped factory status to determine whether renewable electricity is applied."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-02','Supplier role','{"seq":25,"stage":"Manufacturing","source_field":"PEF Logic H","rule":"Forming is calculated for a renewable manufacturer; printing/branding renewable logic applies to manufacturer or printer. Trader or retailer are excluded as the fact they are using renewable energy will not have an impact."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-03','Forming process','{"seq":26,"stage":"Manufacturing","source_field":"Sheets 1-1 and 2-3","rule":"Derive the forming process from the substrate mapping and apply the mapped process efficiency."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-04','Manufacturing energy','{"seq":27,"stage":"Manufacturing","source_field":"Sheet 2-1 (1)","rule":"For each mapped forming, printing or branding process, retrieve the energy required per reference unit from sheet 2-1 (1): electricity (kWh), natural gas (MJ), other heat (MJ) and steam (kg). Example from the notes: Flexo requires 0.0559503 kWh of electricity and 0.1264 MJ of natural gas per m2."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-05','Process amount','{"seq":28,"stage":"Manufacturing","source_field":"PEF Logic AS / AX / BC + Extract V:X","rule":"Forming amount is based on material kg. Printing and branding amounts are based on the treated surface area entered in m2. Multiply the process energy per m2 by that surface area. Example: 1.5 m2 of Flexo requires 0.0839254 kWh electricity and 0.1896 MJ natural gas."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-06','Country mapping','{"seq":29,"stage":"Manufacturing","source_field":"Sheet 2-2","rule":"Use PO Ship From as the manufacturing country and sheet 2-2 to select the mapped activity for each energy carrier. Electricity uses the country medium-voltage market (or renewable electricity where applicable); natural gas uses the mapped heat activity."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-07','Renewable electricity','{"seq":30,"stage":"Manufacturing","source_field":"Factory renewable status + sheet 2-2","rule":"When the qualifying factory is renewable, replace only grid electricity with the mapped RENEWABLE_ELECTRICITY_kWh activity. Natural gas, other heat and steam remain calculated with their normal country-specific activities."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-08','Printing mapping','{"seq":31,"stage":"Manufacturing","source_field":"Sheet 2-1 (2)","rule":"Translate the Sourcing Hub printing label to the activity name used in sheet 2-1 (1)."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-09','Branding mapping','{"seq":32,"stage":"Manufacturing","source_field":"Sheet 2-1 (2)","rule":"Translate the Sourcing Hub branding label to the activity name used in sheet 2-1 (1)."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-10','Energy impact','{"seq":33,"stage":"Manufacturing","source_field":"Sheet 2-2 + ecoinvent","rule":"Calculate each energy carrier separately, then add them: process impact = process amount × Σ(energy requirement per reference unit × country-specific emission factor). Flexo example for 1.5 m2: electricity = 0.0839254 × 0.2626423 = 0.0220424 kg CO2-eq; natural gas = 0.1896 × 0.0541437 = 0.0102656 kg CO2-eq; total = 0.0323080 kg CO2-eq."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-11','Phase 2 total','{"seq":34,"stage":"Manufacturing","source_field":"PEF Logic BE","rule":"Manufacturing impact = forming impact + printing impact + branding impact. Each printing or branding result already includes the sum of all applicable energy carriers."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','MFG-12','Excluded','{"seq":35,"stage":"Manufacturing","source_field":"Anthesis boundary","rule":"Materials and waste associated with forming, printing and branding are excluded; only mapped process energy is included."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-01','Country electricity mapping','{"seq":38,"stage":"Usage","source_field":"PEF Logic!D + sheet 4","rule":"Use PO Ship To (country code in PEF Logic column D) to retrieve the ecoinvent activity, reference product, geography and reference amount."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-02','Market group = FALSE','{"seq":39,"stage":"Usage","source_field":"Sheet 4, column F","rule":"A direct country-level electricity market is used: market for electricity, low voltage."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-03','Market group = TRUE','{"seq":40,"stage":"Usage","source_field":"Sheet 4, column F","rule":"No matching direct country market is used; apply the broader regional or global mix: market group for electricity, low voltage."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-04','Usage duration','{"seq":41,"stage":"Usage","source_field":"PEF Logic!BJ / Time Usage","rule":"Convert the activation period into total usage hours."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-05','Power Grid - total kWh','{"seq":42,"stage":"Usage","source_field":"Extract!AB or Extract!AD","rule":"The user enters the equipment''s kWh consumption per hour. Total lifecycle kWh = entered kWh × total usage hours."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-06','Batteries - total kWh','{"seq":43,"stage":"Usage","source_field":"Extract!AB or Extract!AD","rule":"The user enters the equipment''s kWh consumption per hour. Total lifecycle kWh = entered kWh × total usage hours. No battery-efficiency adjustment is applied."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-07','Solar','{"seq":44,"stage":"Usage","source_field":"Electronics / Lighting Type","rule":"Current model assumption: use-phase impact = 0 because no solar electricity factor is defined in sheet 4."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-08','Electricity factor','{"seq":45,"stage":"Usage","source_field":"Sheet 4 + ecoinvent","rule":"Factor (kg CO2-eq/kWh) = ecoinvent climate impact ÷ ecoinvent reference amount ÷ mapping reference amount."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-09','Electronics impact','{"seq":46,"stage":"Usage","source_field":"PEF Logic!BM","rule":"Electronics impact = electronics total lifecycle kWh × electricity factor for the country of use."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-10','Lighting impact','{"seq":47,"stage":"Usage","source_field":"PEF Logic!BP","rule":"Lighting impact = lighting total lifecycle kWh × electricity factor for the country of use."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-11','Total Use impact','{"seq":48,"stage":"Usage","source_field":"PEF Logic!BQ","rule":"Total Use impact = electronics impact + lighting impact."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-12','Boundary','{"seq":49,"stage":"Usage","source_field":"Use phase","rule":"The calculation covers electricity consumption only. Battery manufacture, replacement and end-of-life are excluded."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','USE-13','Data interpretation','{"seq":50,"stage":"Usage","source_field":"Extract!AB / Extract!AD","rule":"For both Power Grid and Batteries, the entered kWh is the equipment''s hourly consumption. The model calculates total lifecycle kWh by multiplying it by total usage hours."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-01','Origin and destination','{"seq":53,"stage":"Distribution","source_field":"PEF Logic BB:BC","rule":"Use PO Ship From and PO Ship To country names for the transport matrix and shipping geography."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-02','Transport mode','{"seq":54,"stage":"Distribution","source_field":"Countries matrix","rule":"If origin equals destination, assign Road. Otherwise use the mapped preferred/default route from the Countries sheet."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-03','Transported weight','{"seq":55,"stage":"Distribution","source_field":"PEF Logic R","rule":"Convert material weight from kg to metric tonnes before multiplying by distance."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-04','Road activity','{"seq":56,"stage":"Distribution","source_field":"PEF Logic BE","rule":"Road tonne-km = transported tonnes × road distance in km."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-05','Sea activity','{"seq":57,"stage":"Distribution","source_field":"PEF Logic BG","rule":"Sea tonne-km = transported tonnes × sea distance in km; use 0 when the route has no sea leg."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-06','Plane activity','{"seq":58,"stage":"Distribution","source_field":"PEF Logic BH","rule":"Plane tonne-km = transported tonnes × air distance in km; classify the aircraft range using distance, not tonne-km."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-07','Truck class','{"seq":59,"stage":"Distribution","source_field":"PEF Logic BF","rule":"Assuming >32 t trucks.","assumption":"Assuming >32 t trucks."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-08','Transport factor','{"seq":60,"stage":"Distribution","source_field":"Sheet 3 + ecoinvent","rule":"Select the activity, reference product and geography by country, mode, truck class or air-distance range, then calculate the factor per tonne-km.  \r\nTransport, freight, sea, container ship, heavy fuel oil is used as assumption for ship"}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-09','Phase 3 total','{"seq":61,"stage":"Distribution","source_field":"PEF Logic BI","rule":"Distribution impact = road tonne-km × road factor + sea tonne-km × sea factor + plane tonne-km × plane factor."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-10','Boundary','{"seq":62,"stage":"Distribution","source_field":"Current model","rule":"Only the mapped origin-to-destination movement is included. Warehousing, storage energy, packaging volume constraints and return journeys are excluded. Multidelivery are also excluded."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','DIST-11','Consolidation assumption','{"seq":63,"stage":"Distribution","source_field":"Road freight","rule":"The tonne-km factor represents allocated freight activity; the product does not need to occupy the full vehicle."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-01','Material mapping','{"seq":66,"stage":"End of Life","source_field":"PEF Logic!J + sheet 5-1","rule":"Map each substrate to its EOL material category, classification and technical recyclability."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-02','Gate 1','{"seq":67,"stage":"End of Life","source_field":"PEF Logic!AQ / BV / DA + sheet 5-1","rule":"Evaluate technical recyclability separately for each active substrate. Y only when that substrate is mapped as technically recyclable in sheet 5-1.","assumption":"Substrate-level gate."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-03','Gate 2','{"seq":68,"stage":"End of Life","source_field":"Derived in EOL formulas","rule":"Treat the product as mono-material when all active substrates map to one EOL material classification. A mono-material product does not require a positive separation input.","assumption":"Product-level condition."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-04','Gate 3','{"seq":69,"stage":"End of Life","source_field":"Extract!AY","rule":"Easy material separation is evaluated at product level. For a multi-material product, recycling is allowed only when this input is Yes.","assumption":"Product-level condition."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-05','Gate 4','{"seq":70,"stage":"End of Life","source_field":"PEF Logic!AR / BW / DB","rule":"Evaluate recycling impediments separately for each substrate using its own coating, plus product printing and branding. Y only where these impediments are absent.","assumption":"Substrate-level gate; conservative screening."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-06','Gate 5','{"seq":71,"stage":"End of Life","source_field":"PEF Logic!AS / BX / DC + Extract!BS:BU / DA:DC / DG:DI","rule":"Evaluate the >5 cm threshold separately for each active substrate using its dedicated finished dimensions: substrate 1 uses Extract BT length, BU width and BS unit; substrate 2 uses DA length, DB width and DC unit; substrate 3 uses DG length, DH width and DI unit. Both length and width must be at least 5 cm after unit conversion.","assumption":"Substrate-level gate; no fallback to global product dimensions."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-07','Recyclability result','{"seq":72,"stage":"End of Life","source_field":"Substrate gates + mono-material / separation rule","rule":"Apply the recycling rate to a substrate only when its Gates 1, 4 and 5 are Y and the product is mono-material or easily separable. If a recyclable and a non-recyclable substrate are easily separable, only the recyclable substrate receives the recycling rate. If a multi-material product cannot be separated, no substrate is treated as recycled.","assumption":"Calculated inside the EOL destination formulas."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-08','EOL geography','{"seq":73,"stage":"End of Life","source_field":"PEF Logic!D / PO Ship To","rule":"Use the destination country code to select country-specific fate rates."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-09','Recyclable component','{"seq":74,"stage":"End of Life","source_field":"Sheet 5-2","rule":"Apply the country- and classification-specific recycling, incineration and landfill rates."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-10','Non-recyclable component','{"seq":75,"stage":"End of Life","source_field":"Sheet 5-2","rule":"Set recycling to 0% and re-normalise incineration and landfill so that their sum equals 100%."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-11','EOL amounts','{"seq":76,"stage":"End of Life","source_field":"PEF Logic!Q / AV / CA","rule":"Destination amount = net substrate weight, without process-efficiency adjustment, multiplied by the applicable destination rate."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-12','Recycling impact','{"seq":77,"stage":"End of Life","source_field":"Anthesis cut-off approach","rule":"Excluded from EOL impact; no recycling credit is awarded."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-13','Incineration / landfill impact','{"seq":78,"stage":"End of Life","source_field":"Sheet 5-3 + ecoinvent","rule":"Destination amount × mapped ecoinvent treatment factor."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-14','Excluded','{"seq":79,"stage":"End of Life","source_field":"Anthesis methodology","rule":"Transport to EOL and printing/branding materials are excluded."}'::jsonb,'active','2026-01-01',null),
('pef_methodology','EOL-15','Source','{"seq":80,"stage":"End of Life","source_field":"Anthesis deliverables","rule":"adm_Indicia_LCA_Database_Documentation_2026 and Example Calculations_v2."}'::jsonb,'active','2026-01-01',null);
insert into public.library_records (library_key, code, name, data, status, effective_from, notes) values
('pef_open_issues','EOL-01','The mono-material formula appears incorrect.','{"seq":5,"issue_id":"EOL-01","severity":"high","location":"Example Calculations_v2 — Scenarios 1–3, Gate 2","issue":"The mono-material formula appears incorrect.","evidence":"COUNTA(UNIQUE(material range))<1 cannot be TRUE for a non-empty range. Scenario 4 instead uses =1, which is logically consistent.","recommendation":"Replace <1 with =1, or explicitly define whether Gate 2 applies per product or per component.","current_treatment":"PEF Logic assumes Y because each current row models one substrate component.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-02','The final recyclability result does not consistently combine all five gates.','{"seq":6,"issue_id":"EOL-02","severity":"high","location":"Example Calculations_v2 — Scenarios 1–2, TECHNICALLY_RECYCLABLE","issue":"The final recyclability result does not consistently combine all five gates.","evidence":"Scenario 1 contains hard-coded Y/N outcomes despite failed gates. Scenario 2 largely reuses the sheet 5-1 technical tag while Gates 2–5 can be FALSE. Recycling may therefore be applied to an item that fails the hierarchy.","recommendation":"Define the final rule explicitly; recommended: Y only when Gates 1–5 are all Y.","current_treatment":"PEF Logic requires every gate to be Y.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-03','The documentation requires the outcome of the EOL Gates Hierarchy, but the input section exposes only two user questions.','{"seq":7,"issue_id":"EOL-03","severity":"high","location":"Documentation §5.5 vs Example Calculations_v2","issue":"The documentation requires the outcome of the EOL Gates Hierarchy, but the input section exposes only two user questions.","evidence":"The calculation table contains five gates: technical recyclability, mono-material, easy separation, no impediments and minimum size. Three are not clearly sourced from user inputs.","recommendation":"Specify the source and business rule for Gates 2, 3 and 4, and add the missing inputs where they cannot be derived.","current_treatment":"Gate 2 is derived from row structure; Gate 4 is screened from coating/printing/branding; Gate 3 remains a manual input.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-04','The blanket assumption that all products and packaging are disassembled conflicts with the disassembly gate.','{"seq":8,"issue_id":"EOL-04","severity":"medium","location":"Documentation §3.4.4 vs EOL gates","issue":"The blanket assumption that all products and packaging are disassembled conflicts with the disassembly gate.","evidence":"The Word states that all products and packaging are disassembled into material-specific waste streams, while examples allow the answer No to designed-for-disassembly.","recommendation":"Clarify whether disassembly is a universal scenario assumption or a product-specific gate. Do not use both simultaneously.","current_treatment":"Product-specific Gate 3 is used; default N until data is supplied.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-05','Gate 4 is not implemented consistently across scenarios.','{"seq":9,"issue_id":"EOL-05","severity":"medium","location":"Example Calculations_v2 — Gate 4","issue":"Gate 4 is not implemented consistently across scenarios.","evidence":"Scenario 1 shows Gate 4 = FALSE even though its coating input is None; other scenarios use different hard-coded values or logic. This can change the final recycling result materially.","recommendation":"Create one documented obstruction list for coatings, laminates, inks and decorations, and calculate Gate 4 from that list.","current_treatment":"Conservative rule: Y only when coating, printing and branding are absent.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-06','Figure numbering and cross-references are inconsistent.','{"seq":10,"issue_id":"EOL-06","severity":"medium","location":"Documentation §5.5 / Figure references","issue":"Figure numbering and cross-references are inconsistent.","evidence":"The text says Figure 8 provides the EOL implementation schematic, but the EOL schematic is labelled Figure 12; the stage-gate graphic is labelled Figure 11.","recommendation":"Correct the cross-references so implementers can identify the intended decision tree.","current_treatment":"No calculation impact; logged for document correction.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-07','The examples do not clearly show the formula used when an item is not recyclable.','{"seq":11,"issue_id":"EOL-07","severity":"medium","location":"Example Calculations_v2 vs Documentation §5.5","issue":"The examples do not clearly show the formula used when an item is not recyclable.","evidence":"Recycling becomes zero in examples, but the documentation does not explicitly state whether the original incineration/landfill rates must be re-normalised to 100%.","recommendation":"Document the redistribution rule and confirm that incineration + landfill must equal 100% after recycling is removed.","current_treatment":"PEF Logic re-normalises incineration and landfill to 100%.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-08','Several labels contain typos or ambiguous units.','{"seq":12,"issue_id":"EOL-08","severity":"low","location":"Example Calculations_v2 / labels and wording","issue":"Several labels contain typos or ambiguous units.","evidence":"Examples include ''Reaonsing'', ''techncally'', ''Rewable'', and kWh fields described inconsistently as lifetime consumption versus hourly equipment consumption.","recommendation":"Standardise labels and define each energy field''s unit and time basis in the data dictionary.","current_treatment":"Use-phase assumptions state that entered kWh is hourly consumption multiplied by total hours.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-09','The scope of product components is not fully aligned with the current row-level implementation.','{"seq":13,"issue_id":"EOL-09","severity":"medium","location":"Documentation §5.5 and examples","issue":"The scope of product components is not fully aligned with the current row-level implementation.","evidence":"Anthesis examples can assess several components separately (substrate, electronics, battery and packaging). A single aggregated substrate row cannot reproduce component-specific classifications and treatment factors.","recommendation":"Confirm whether production data will provide one row per component. If not, add a component-level EOL table before final deployment.","current_treatment":"Current calculation covers the substrate represented by PEF Logic!J/R only; electronics, batteries and packaging need component weights to be added.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','EOL-10','The examples use small unit-product weights, while the current PEF Logic rows contain order-level weights near 1,000 kg.','{"seq":14,"issue_id":"EOL-10","severity":"high","location":"Example Calculations_v2 vs operational dataset","issue":"The examples use small unit-product weights, while the current PEF Logic rows contain order-level weights near 1,000 kg.","evidence":"EOL impact changes by orders of magnitude depending on whether the functional unit is one product or the whole order. Anthesis defines the functional unit as one promotional product.","recommendation":"Confirm whether PEF Logic material weight is per unit or per order and normalise to the functional unit before reporting product-level PEF.","current_treatment":"No automatic conversion applied; current EOL uses PEF Logic total material weight.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','GEN-01','The same filename exists in materially different versions.','{"seq":15,"issue_id":"GEN-01","severity":"high","location":"Two indexed copies of Example Calculations_v2","issue":"The same filename exists in materially different versions.","evidence":"The latest indexed copy reports Scenario 2 Material Acquisition = 0.3433547, while another indexed copy reports 2.606814. Results cannot be reproduced reliably without a controlled version.","recommendation":"Agree one authoritative file, add a version/date to the filename and archive superseded copies.","current_treatment":"Review is based on the SharePoint deliverable modified 16 Oct 2026; the alternative copy is not used.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','SCOPE-01','The calculation basis may mix one-product and whole-order quantities across every phase.','{"seq":16,"issue_id":"SCOPE-01","severity":"high","location":"Documentation functional unit vs PEF Logic weights","issue":"The calculation basis may mix one-product and whole-order quantities across every phase.","evidence":"Anthesis defines the functional unit as one promotional product, while PEF Logic currently contains weights near 1,000 kg and energy entries that may represent an order or equipment rate. Every phase scales directly with these quantities.","recommendation":"Define each input as per-unit or per-order and normalise all stages to one declared functional unit before totals are reported.","current_treatment":"No automatic normalisation is applied; results follow the quantities entered.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MAT-01','Need calculation for coating weight / area','{"seq":17,"issue_id":"MAT-01","severity":"medium","location":"Coating weight & Area TODO","issue":"Need calculation for coating weight / area","evidence":"Retrieve L´Oreal assumptions and include the logic in the documentation","recommendation":"Retrieve L´Oreal assumptions and include the logic in the documentation","current_treatment":"Manual entry for now","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MAT-02','Coating names are not confirmed against Sourcing Hub values.','{"seq":18,"issue_id":"MAT-02","severity":"medium","location":"Sheet 1-3 and Assumptions TODO","issue":"Coating names are not confirmed against Sourcing Hub values.","evidence":"The mapping sheet still contains ''CHANGE THE NAMES TO MATCH EXACTLY SOURCING HUB ONES''. Exact-match or text-search logic can miss factors or select the wrong coating.","recommendation":"Complete and approve a controlled Sourcing Hub-to-Anthesis mapping table.","current_treatment":"Current formulas use the names presently stored in sheet 1-3.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MFG-01','Several branding energy factors are not supported by a technical source.','{"seq":19,"issue_id":"MFG-01","severity":"high","location":"Sheet 2-1 (1) — branding energy sources","issue":"Several branding energy factors are not supported by a technical source.","evidence":"Dye, Embossing Blind/Foil, Pad Printing, Sublimation and Thermal Transfer cite copilot.microsoft.com rather than a dataset, study or supplier measurement.","recommendation":"Replace each value with a traceable source and document uncertainty or proxy selection.","current_treatment":"Current model uses the entered factors unchanged; affected results should be treated as provisional.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MFG-02','The mapping for several branding processes remains unresolved.','{"seq":20,"issue_id":"MFG-02","severity":"high","location":"Sheet 2-1 (2) — branding mapping notes","issue":"The mapping for several branding processes remains unresolved.","evidence":"The sheet asks ''Which activity apply for those? Can we use most approx one?'' while factors have already been populated for Dye, Embossing, Pad Printing, Sublimation and Thermal Transfer.","recommendation":"Approve explicit mappings before production use and separate measured factors from proxies.","current_treatment":"Current model applies the populated process with the matching Sourcing Hub label.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MFG-03','Manufacturing geography may be proxied by PO Ship From rather than the actual factory location.','{"seq":21,"issue_id":"MFG-03","severity":"medium","location":"Anthesis examples vs PEF Logic manufacturing geography","issue":"Manufacturing geography may be proxied by PO Ship From rather than the actual factory location.","evidence":"Anthesis scenarios specify a Manufacturing Location. PEF Logic energy formulas use the code in PO SHIP FROM; this may differ from the factory country, especially for traders and multi-site suppliers.","recommendation":"Use a verified Factory Country field, falling back to PO Ship From only when documented.","current_treatment":"Current manufacturing factors use PEF Logic column C / PO Ship From.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MFG-04','The forming boundary can create double-counting or omission if the mapping flags are wrong.','{"seq":22,"issue_id":"MFG-04","severity":"high","location":"Material processing vs Manufacturing forming","issue":"The forming boundary can create double-counting or omission if the mapping flags are wrong.","evidence":"The model removes forming from material acquisition and adds manufacturing energy only for selected renewable-factory cases. This depends on INCLUDES_FORMING, raw-material and process mappings being mutually consistent.","recommendation":"Add a row-level control proving forming is included exactly once for every substrate and renewable scenario.","current_treatment":"Current logic switches between processed material factors and separate forming energy; no explicit one-time inclusion check exists.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','DIST-01','The model replaces leg-specific vehicles with a distance-based truck heuristic.','{"seq":23,"issue_id":"DIST-01","severity":"high","location":"Example Calculations_v2 vs PEF Logic truck class","issue":"The model replaces leg-specific vehicles with a distance-based truck heuristic.","evidence":"Anthesis examples use different truck classes by journey leg. PEF Logic assigns one class from total road distance (<=100, <=300, >300 km), so the selected emission factor may not match the actual legs.","recommendation":"Store vehicle class per road leg or define and approve a documented default hierarchy.","current_treatment":"Current model applies one truck class to all road tonne-kilometres.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','DIST-02','The route structure is simplified relative to the examples.','{"seq":24,"issue_id":"DIST-02","severity":"high","location":"Example Calculations_v2 vs Countries matrix","issue":"The route structure is simplified relative to the examples.","evidence":"Anthesis examples calculate separate origin-road, sea/air and destination-road legs. The matrix aggregates road distance and permits only one road class, limiting traceability and preventing different vehicle assumptions by leg.","recommendation":"Add explicit leg columns or a separate journey-leg table with mode, distance, vehicle and tonne-km per leg.","current_treatment":"Current model combines road feeders and calculates one sea or plane distance from the Countries matrices.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','DIST-03','Transported weight does not clearly include all product components and packaging.','{"seq":25,"issue_id":"DIST-03","severity":"high","location":"Documentation/examples vs PEF Logic transported weight","issue":"Transported weight does not clearly include all product components and packaging.","evidence":"Anthesis examples sum product components and primary packaging. PEF Logic distribution uses total substrate weight; the sheet itself notes packaging still needs to be added.","recommendation":"Define total shipped mass as all substrates, electronics, batteries, coatings where material, and packaging, with a weight reconciliation.","current_treatment":"Current distribution uses PEF Logic column R for the represented substrate.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','USE-01','The energy input time basis is inconsistent.','{"seq":26,"issue_id":"USE-01","severity":"high","location":"Example Calculations_v2 input label vs current Use logic","issue":"The energy input time basis is inconsistent.","evidence":"Anthesis examples label the field ''Lifetime energy Consumption (kWh)''. The current model treats the entered kWh as hourly consumption and multiplies it by activation hours. If the input is already lifetime kWh, impact is multiplied twice.","recommendation":"Rename the field to kWh/hour or use lifetime kWh directly; obtain written confirmation from Anthesis/data owners.","current_treatment":"Current model follows the user''s stated rule: entered kWh per hour multiplied by total usage hours.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','USE-02','Manual hour values conflict with the approved activation table.','{"seq":27,"issue_id":"USE-02","severity":"high","location":"Time Usage vs PEF Logic rows 5–7","issue":"Manual hour values conflict with the approved activation table.","evidence":"Time Usage maps 1 day to 8 hours, 2–7 days to 36 hours and 8–13 days to 84 hours, but PEF Logic rows 5–7 currently show 1 hour. Use impacts are therefore understated by factors of 8, 36 and 84 where energy is present.","recommendation":"Restore formula-driven hours for every populated row and prohibit manual overrides unless explicitly flagged.","current_treatment":"Rows 8–10 use the Time Usage mapping; rows 5–7 currently retain manual example values.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','USE-03','Solar electricity is assigned zero impact without a solar lifecycle factor.','{"seq":28,"issue_id":"USE-03","severity":"high","location":"Use methodology / sheet 4","issue":"Solar electricity is assigned zero impact without a solar lifecycle factor.","evidence":"Zero may represent no grid purchase, but photovoltaic generation and storage still have lifecycle impacts. A zero assumption is not equivalent to a documented solar electricity dataset.","recommendation":"Map solar electricity to an approved ecoinvent activity or clearly label zero as an excluded-impact scenario assumption.","current_treatment":"Current Use formulas return zero for Yes, Solar because sheet 4 has no solar factor.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','USE-04','Battery-powered products are represented only by charging electricity unless separate component weights are provided.','{"seq":29,"issue_id":"USE-04","severity":"medium","location":"Use and EOL component boundaries","issue":"Battery-powered products are represented only by charging electricity unless separate component weights are provided.","evidence":"Battery manufacture, replacement and treatment can be material. Anthesis Scenario 3 models a battery as an EOL component, but the current row-level model has no battery weight input.","recommendation":"Add battery chemistry, capacity/weight and replacement count, or explicitly exclude these impacts with a limitation statement.","current_treatment":"Use includes charging electricity; battery manufacturing and EOL are excluded unless captured as separate material components.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','MAT-02 (2)','Bring data inputs and full calculations','{"seq":30,"issue_id":"MAT-02","severity":"medium","location":"Material Weight","issue":"Bring data inputs and full calculations","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','PORT-01','Coating factors use PO Ship To, materials use PO Ship From','{"seq":1000,"issue_id":"PORT-01","severity":"medium","location":"PEF Logic AP / BU / CZ (coating impact)","issue":"Coating impact picks the ecoinvent geography from PO Ship To, while virgin and recycled material use PO Ship From.","evidence":"The coating formulas set the country from column C (ship to); the material formulas use column B (ship from). The methodology says geography follows PO Ship From.","recommendation":"Confirm with Anthesis which geography coatings should use and align the formula.","current_treatment":"System Guy reproduces the workbook (ship to) so results match; flip the ''coating_geography'' parameter once confirmed.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','PORT-02','PEF score inside the Impact Grade: functional unit','{"seq":1001,"issue_id":"PORT-02","severity":"high","location":"PEF Logic GF / GG → Impact Grade sub-score","issue":"This model produces the PEF score (weighted single score, Pt / mPt). The Impact Grade (Impact Grade.xlsx) uses it as half the grade, scaled against the 95th percentile of our PEF scores.","evidence":"Per-order and per-unit PEF results differ by orders of magnitude (SCOPE-01): the PEF scores compared against the reference must share one functional unit, or the percentile mixes order lines with single products.","recommendation":"Settle the functional unit (per product or per order line) before PEF results are stored for specs and the reference is recalculated.","current_treatment":"Reference seeded from the 6 worked examples (order lines). Letters A 80+, B 60+, C 40+, D 20+, E below are provisional.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','PORT-03','Printing and branding use renewable electricity for any supplier role','{"seq":1002,"issue_id":"PORT-03","severity":"medium","location":"PEF Logic DM / DR (DI, DN unused)","issue":"Printing and branding switch to renewable electricity whenever the factory is renewable, whatever the supplier type.","evidence":"Columns DI and DN work out ''renewable manufacturer or printer'' but DM and DR test only column F (factory renewable). The methodology excludes traders and retailers.","recommendation":"Use the DI / DN result in the printing and branding formulas.","current_treatment":"System Guy reproduces the workbook so results match.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','PORT-04','Flight range is classified from km × 1000','{"seq":1003,"issue_id":"PORT-04","severity":"medium","location":"PEF Logic EG (planeDist)","issue":"The plane distance used to pick short, medium or long haul is tonne-km ÷ (tonnes ÷ 1000), which is the air distance × 1000.","evidence":"Any air leg is therefore classed as ''> 4000km''. None of the worked examples has an air leg, so no current result is affected.","recommendation":"Classify the range from the air distance in km.","current_treatment":"System Guy reproduces the workbook so results match.","status":"open"}'::jsonb,'active','2026-01-01',null),
('pef_open_issues','PORT-05','Coating end of life is in the CO2e total but not in the single score','{"seq":1004,"issue_id":"PORT-05","severity":"high","location":"PEF Logic EU / EV vs Impact Calc (EOL rows)","issue":"PEF Logic adds incineration and landfill of the coating mass to the end-of-life CO2e; Impact Calc, which feeds the 16 categories and the single score, leaves it out.","evidence":"Worked example 4 (Duplex Board with 0.25 kg Gloss Lamination): PEF Logic total 2.871 kg CO2e, Impact Calc climate change 2.520 kg CO2e. The other worked examples have no coating weight and agree.","recommendation":"Decide whether coatings go to end of life and make both sheets do the same.","current_treatment":"Parameter coating_end_of_life = include (as PEF Logic). Set it to exclude to reproduce the workbook''s single score exactly.","status":"open"}'::jsonb,'active','2026-01-01',null);
